solution.solution.c:
#include <stdbool.h>
#include <stddef.h>

void swap(int *a, int *b)
{
    int temp = *a;
    *a = *b;
    *b = temp;
}

bool divide(int a, int b, int *quotient, int *remainder)
{
    if (b == 0) return false;
    *quotient = a / b;
    if (remainder != NULL) *remainder = a % b;
    return true;
}

bool min_max(const int *values, size_t count, int *min, int *max)
{
    if (count == 0) return false;
    *min = values[0];
    *max = values[0];
    for (size_t i = 1; i < count; i++) {
        if (values[i] < *min) *min = values[i];
        if (values[i] > *max) *max = values[i];
    }
    return true;
}

void sort3(int *a, int *b, int *c)
{
    if (*a > *b) swap(a, b);
    if (*b > *c) swap(b, c);
    if (*a > *b) swap(a, b);
}

unitTests:
TEST("swapping") { int x = 1, y = 2; swap(&x, &y); CHECK_EQ(x, 2); CHECK_EQ(y, 1); }
TEST("dividing") { int q = 0, r = 0; CHECK(divide(17, 5, &q, &r)); CHECK_EQ(q, 3); CHECK_EQ(r, 2); CHECK(divide(20, 4, &q, &r)); CHECK_EQ(q, 5); CHECK_EQ(r, 0); }
TEST("dividing by zero stores nothing") { int q = 99, r = 99; CHECK(!divide(5, 0, &q, &r)); CHECK_EQ(q, 99); CHECK_EQ(r, 99); }
TEST("the remainder is optional") { int q = 0; CHECK(divide(9, 2, &q, NULL)); CHECK_EQ(q, 4); }
TEST("min and max") { int a[] = {5, -2, 9, 0}; int lo = 0, hi = 0; CHECK(min_max(a, 4, &lo, &hi)); CHECK_EQ(lo, -2); CHECK_EQ(hi, 9); int one[] = {7}; CHECK(min_max(one, 1, &lo, &hi)); CHECK_EQ(lo, 7); CHECK_EQ(hi, 7); CHECK(!min_max(a, 0, &lo, &hi)); }
TEST("sorting three") { int a = 3, b = 1, c = 2; sort3(&a, &b, &c); CHECK_EQ(a, 1); CHECK_EQ(b, 2); CHECK_EQ(c, 3); int d = 9, e = 8, f = 7; sort3(&d, &e, &f); CHECK_EQ(d, 7); CHECK_EQ(e, 8); CHECK_EQ(f, 9); int g = 1, h = 1, i = 0; sort3(&g, &h, &i); CHECK_EQ(g, 0); CHECK_EQ(h, 1); CHECK_EQ(i, 1); }

